using System;using System.IO;using System.Linq;using Musikbox;
class Media57Tests {static void Main(string[] args){int count=0;foreach(string extension in new[]{"mp4","mkv"}){string source=Path.GetFullPath("verify/video-test."+extension),err;Ffmpeg.Run("/usr/bin/ffmpeg","-v error -y -f lavfi -i color=c=black:s=160x120:d=2 -f lavfi -i sine=frequency=550:duration=2 -c:v mpeg4 -c:a aac -shortest -metadata title=Testvideo "+Ffmpeg.Quote(source),()=>{},out err);byte[] before=File.ReadAllBytes(source);var song=MediaProbe57.Read(source,"/usr/bin/ffmpeg",()=>{});if(song.Title!="Testvideo"||song.Duration<1.9)throw new Exception("Medienanalyse "+extension);count++;string target=AudioAdvanced.FfmpegBatch(new[]{song},Path.GetFullPath("verify/qa-media"),"/usr/bin/ffmpeg",new AudioOptions{Format="MP3",Mode="Audio extrahieren"},()=>{},(n,t,s)=>{});if(Directory.GetFiles(target,"*.mp3").Length!=1||!before.SequenceEqual(File.ReadAllBytes(source)))throw new Exception("Extraktion oder Quelldatei "+extension);count++;Console.WriteLine("PASS "+extension+" mit Video und Ton → MP3, Quelle bytegleich");}Console.WriteLine("BESTANDEN: "+count+" Prüfungen echter Video-/Audioextraktion");}}
